  "mlsGroupId": "<base64url MLS group ID>",
  "commits": [
    {
      "epoch": 42,
      "proposals": [
        "<base64url MLS PublicMessage carrying a Proposal>"
      ],
      "content": "<base64url MLS PublicMessage carrying the Commit>"
    }
  ]
}

figure.artwork:
struct {
  opaque ocm_address<V>;
} Admin;

struct {
  opaque group_ocm_address<V>;
  Admin admins<V>;
} OCMCommunity;

figure.sourcecode:
{
  "notificationType": "MLS_WELCOME",
  "senderDomain": "othercloud.example.org",
  "shareType": "community",
  "notification": {
    "community": {
      "mlsGroupId": "<base64url MLS group ID>",
      "userId": "bob@othercloud.example.org",
      "content": "<base64url MLS Welcome wire format>"
    }
  }
}

{
  "notificationType": "MLS_PROPOSAL",
  "senderDomain": "cloud.example.org",
  "shareType": "community",
  "notification": {
    "community": {
      "mlsGroupId": "<base64url MLS group ID>",
      "content": "<base64url MLS PublicMessage carrying the Proposal>"
    }
  }
}

{
  "notificationType": "MLS_COMMIT",
  "senderDomain": "cloud.example.org",
  "shareType": "community",
  "notification": {
    "community": {
      "mlsGroupId": "<base64url MLS group ID>",
      "proposals": [
        "<base64url MLS PublicMessage carrying a Proposal>"
      ],
      "content": "<base64url MLS PublicMessage carrying the Commit>"
    }
  }
}

{
  "notificationType": "MLS_APPLICATION",
  "senderDomain": "cloud.example.org",
  "shareType": "community",
  "notification": {
    "community": {
      "mlsGroupId": "<base64url MLS group ID>",
      "content": "<base64url MLS PrivateMessage wire format>"
    }
  }
}

section.t:
The volume of MLS_APPLICATION traffic produced by this rule grows with
the number of shared resources and the frequency of epoch transitions;
see the batching item in Open Issues.

figure.artwork:
struct {
  opaque server_url<V>;
} FederationAdmin;

struct {
  opaque federation_id<V>;
  opaque federation_name<V>;
  FederationAdmin admins<V>;
} OCMServersFederation;

figure.sourcecode:
{
  "notificationType": "MLS_WELCOME",
  "senderDomain": "ocm-server.example.org",
  "resourceType": "federation",
  "notification": {
    "federation": {
      "federationId": "sciencemesh",
      "mlsGroupId": "<base64url MLS group ID>",
      "serverUrl": "https://cloud.example.org",
      "content": "<base64url MLS Welcome wire format>"
    }
  }
}
